import re

with open('references.bib') as f:
    lines = f.readlines()

# Rebuild entries properly
entries = {}
current_key = None
current_body = []
current_type = None

for line in lines:
    entry_match = re.match(r'@(\w+)\{([^,]+),', line)
    if entry_match:
        if current_key:
            entries[current_key] = {'type': current_type, 'body': ''.join(current_body)}
        current_type = entry_match.group(1)
        current_key = entry_match.group(2)
        current_body = [line]
    elif current_key:
        current_body.append(line)

if current_key:
    entries[current_key] = {'type': current_type, 'body': ''.join(current_body)}

print('=== TITLE CASE PROTECTION (FULL TITLE ANALYSIS) ===\n')

for key, data in entries.items():
    body = data['body']
    # Extract full title value - handle nested braces
    title_start = body.find('title=')
    if title_start == -1:
        title_start = body.find('title =')
    if title_start == -1:
        continue

    # Find the title value - count brace depth
    pos = body.index('{', title_start)
    depth = 0
    title_chars = []
    for i in range(pos, len(body)):
        if body[i] == '{':
            depth += 1
        elif body[i] == '}':
            depth -= 1
            if depth == 0:
                break
        if depth >= 1:
            title_chars.append(body[i])

    full_title = ''.join(title_chars)[1:]  # skip the opening brace

    # Now check: remove braced content and look for unprotected uppercase
    def remove_braces(s):
        result = []
        depth = 0
        for c in s:
            if c == '{':
                depth += 1
                result.append(' ')
            elif c == '}':
                depth -= 1
                result.append(' ')
            elif depth == 0:
                result.append(c)
            else:
                result.append(' ')
        return ''.join(result)

    unbraced = remove_braces(full_title)
    acronyms = re.findall(r'[A-Z]{2,}', unbraced)

    if acronyms:
        print(f'[{key}]')
        print(f'  Full title: {full_title}')
        print(f'  Unprotected uppercase sequences: {acronyms}')
        print()

if not any(re.findall(r'[A-Z]{2,}', remove_braces(
    ''.join(entries[k]['body'].split('title')[1].split('},')[0] if 'title' in entries[k]['body'] else '')
)) for k in entries):
    print('(none found)')
